'use client';
import { useEffect, useId, useMemo, useRef, useState, type CSSProperties, type KeyboardEvent } from 'react';
import { useStudioMotion } from '../../motion';
import type { EffectProps } from '../../types';
import styles from './styles.module.css';

type Params = { links: string; origin: string; tone: string; duration: number; stagger: number };

export default function FullscreenMenuCurtain({ params }: EffectProps<Params>) {
  const { reduced, scale } = useStudioMotion();
  const navId = useId();
  const [open, setOpen] = useState(false);
  const [current, setCurrent] = useState(0);
  const root = useRef<HTMLDivElement>(null);
  const button = useRef<HTMLButtonElement>(null);
  const nav = useRef<HTMLElement>(null);
  const wasOpen = useRef(false);

  const links = useMemo(() => {
    const l = params.links.split(',').map((s) => s.trim()).filter(Boolean).slice(0, 6);
    return l.length ? l : ['Home'];
  }, [params.links]);
  const origin = params.origin === 'top' || params.origin === 'side' ? params.origin : 'button';
  const tone = params.tone === 'signal' || params.tone === 'paper' ? params.tone : 'ink';

  // Focus follows state: into the menu on open, back to the button on close.
  useEffect(() => {
    if (open) nav.current?.querySelector<HTMLAnchorElement>('a')?.focus({ preventScroll: true });
    else if (wasOpen.current && root.current?.contains(document.activeElement)) button.current?.focus({ preventScroll: true });
    wasOpen.current = open;
  }, [open]);

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (!open) return;
    if (e.key === 'Escape') { e.preventDefault(); setOpen(false); button.current?.focus({ preventScroll: true }); return; }
    if (e.key !== 'Tab') return;
    // Focus loop: close button ↔ links (the page behind is inert).
    const items = Array.from(nav.current?.querySelectorAll<HTMLAnchorElement>('a') ?? []);
    const first = button.current;
    const last = items[items.length - 1];
    if (!first || !last) return;
    if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
    else if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
  };

  const vars = {
    '--fm-duration': `${Math.round(params.duration * scale.duration)}ms`,
    '--fm-stagger': `${Math.round(params.stagger * scale.stagger)}ms`,
  } as CSSProperties;

  return (
    <div ref={root} className={styles.root} style={vars} data-open={open || undefined} data-origin={origin} data-tone={tone} data-reduced={reduced || undefined} onKeyDown={onKeyDown}>
      <header className={styles.bar}>
        <span className={styles.brand}>Halden <span className={styles.brandMark} aria-hidden="true" /> Vey <span className={styles.brandNote}>sample site</span></span>
        <button ref={button} type="button" className={styles.toggle} aria-expanded={open} aria-controls={navId} onClick={() => setOpen((o) => !o)}>
          <span className={styles.toggleLabel}>
            <span data-show={!open || undefined} aria-hidden={open}>Menu</span>
            <span data-show={open || undefined} aria-hidden={!open}>Close</span>
          </span>
          <span className={styles.icon} aria-hidden="true"><span /><span /></span>
        </button>
      </header>

      <div className={styles.page} inert={open}>
        <p className={styles.kicker}>{links[current] ?? links[0]} — issue 12</p>
        <p className={styles.headline}>Quiet interfaces for loud ideas.</p>
        <p className={styles.body}>A fictional studio page that sits behind the menu. Open the menu to see it covered, then pick a link.</p>
      </div>

      <nav ref={nav} id={navId} className={styles.curtain} aria-label="Main (sample)" inert={!open}>
        <ol className={styles.list}>
          {links.map((label, i) => (
            <li key={`${label}-${i}`} className={styles.row} style={{ '--i': i } as CSSProperties}>
              <a
                href={`#${label.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`}
                className={styles.link}
                aria-current={i === current ? 'page' : undefined}
                onClick={(e) => { e.preventDefault(); setCurrent(i); setOpen(false); }}
              >
                <span className={styles.num} aria-hidden="true">{String(i + 1).padStart(2, '0')}</span>
                <span className={styles.mask}><span className={styles.word}>{label}</span></span>
                {i === current ? <span className={styles.here}>You are here</span> : null}
              </a>
            </li>
          ))}
        </ol>
        <p className={styles.foot}><span>hello@haldenvey.example</span><span>Esc to close</span></p>
      </nav>
    </div>
  );
}

.root {
  --fm-bg: var(--mk-ink, #11110f);
  --fm-fg: var(--mk-surface, #fbf9f4);
  --fm-muted: color-mix(in oklab, var(--fm-fg) 58%, var(--fm-bg));
  --fm-hover: var(--mk-signal, #bf2f09);
  --fm-pad: clamp(1rem, 4.5cqi, 2.5rem);
  --fm-bar: 4.25rem;
  position: relative;
  isolation: isolate;
  box-sizing: border-box;
  align-self: stretch;
  width: 100%;
  min-height: 30rem;
  overflow: hidden;
  display: grid;
  grid-template-rows: var(--fm-bar) 1fr;
  color: var(--mk-ink, #11110f);
  font-family: var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
}
.root[data-tone='signal'] {
  --fm-bg: var(--mk-signal, #bf2f09);
  --fm-fg: var(--mk-on-signal, #fff);
  --fm-muted: color-mix(in oklab, var(--fm-fg) 78%, var(--fm-bg));
  --fm-hover: var(--fm-fg);
}
.root[data-tone='paper'] {
  --fm-bg: var(--mk-surface-2, #e9e5da);
  --fm-fg: var(--mk-ink, #11110f);
  --fm-muted: var(--mk-ink-muted, #5c5a52);
}

/* ── Top bar (stays above the curtain) ───────────────────────────────── */
.bar {
  position: relative;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding-inline: var(--fm-pad);
  color: var(--mk-ink, #11110f);
  transition: color var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease) calc(var(--fm-duration) * 0.25);
}
.root[data-open] .bar { color: var(--fm-fg); transition-delay: calc(var(--fm-duration) * 0.12); }
.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.45em;
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: 1.0625rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  white-space: nowrap;
}
.brandMark { width: 0.42em; height: 0.42em; border-radius: 50%; background: var(--mk-signal, #bf2f09); }
.root[data-tone='signal'][data-open] .brandMark { background: currentColor; }
.brandNote {
  margin-left: 0.6em;
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.625rem;
  font-weight: 400;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  opacity: 0.6;
}
@container (max-width: 26rem) { .brandNote { display: none; } }

.toggle {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  min-height: 2.75rem;
  padding: 0 0.4rem 0 0.9rem;
  margin-right: -0.4rem;
  border: 0;
  border-radius: 999px;
  background: none;
  color: inherit;
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
}
.toggle:focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
/* Two stacked labels in one cell: the button never changes width. */
.toggleLabel { display: grid; overflow: clip; text-align: right; }
.toggleLabel > span {
  grid-area: 1 / 1;
  transform: translateY(110%);
  opacity: 0;
  transition: transform var(--mk-duration-moderate, 360ms) var(--mk-ease-emphasized, ease), opacity var(--mk-duration-fast, 160ms) linear;
}
.toggleLabel > span:first-child { transform: translateY(-110%); }
.toggleLabel > span[data-show] { transform: none; opacity: 1; }
.icon {
  position: relative;
  width: 2.25rem;
  height: 2.25rem;
  border: 1px solid currentColor;
  border-radius: 50%;
}
.icon > span {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 0.95rem;
  height: 1.5px;
  margin: -0.75px 0 0 -0.475rem;
  background: currentColor;
  transform: translateY(-3px);
  transition: transform var(--mk-duration-moderate, 360ms) var(--mk-ease-emphasized, ease);
}
.icon > span:last-child { transform: translateY(3px); }
.root[data-open] .icon > span { transform: rotate(45deg); }
.root[data-open] .icon > span:last-child { transform: rotate(-45deg); }

/* ── Page behind ─────────────────────────────────────────────────────── */
.page {
  display: grid;
  align-content: end;
  gap: 0.9rem;
  padding: var(--fm-pad);
  transition: transform var(--fm-duration) var(--mk-ease-emphasized, ease);
}
.root[data-open]:not([data-reduced]) .page { transform: translateY(1.25rem); }
.kicker {
  margin: 0;
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--mk-ink-muted, #5c5a52);
}
.headline {
  margin: 0;
  max-width: 12ch;
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: clamp(2.25rem, 9cqi, 4.75rem);
  font-weight: 700;
  line-height: 0.95;
  letter-spacing: -0.04em;
  text-wrap: balance;
}
.body { margin: 0; max-width: 44ch; font-size: 0.9375rem; line-height: 1.5; color: var(--mk-ink-muted, #5c5a52); }

/* ── Curtain ─────────────────────────────────────────────────────────── */
.curtain {
  --fm-closed: circle(0% at calc(100% - var(--fm-pad) - 0.75rem) calc(var(--fm-bar) / 2));
  --fm-opened: circle(150% at calc(100% - var(--fm-pad) - 0.75rem) calc(var(--fm-bar) / 2));
  position: absolute;
  inset: 0;
  z-index: 2;
  box-sizing: border-box;
  display: grid;
  grid-template-rows: 1fr auto;
  padding: calc(var(--fm-bar) + 0.5rem) var(--fm-pad) var(--fm-pad);
  background: var(--fm-bg);
  color: var(--fm-fg);
  clip-path: var(--fm-closed);
  visibility: hidden;
  transition: clip-path var(--fm-duration) var(--mk-ease-inOut, ease), visibility 0s linear var(--fm-duration);
}
.root[data-origin='top'] .curtain { --fm-closed: inset(0 0 100% 0); --fm-opened: inset(0 0 0 0); }
.root[data-origin='side'] .curtain { --fm-closed: inset(0 0 0 100%); --fm-opened: inset(0 0 0 0); }
.root[data-open] .curtain {
  clip-path: var(--fm-opened);
  visibility: visible;
  transition: clip-path var(--fm-duration) var(--mk-ease-emphasized, ease), visibility 0s;
}
.list {
  align-self: center;
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
}
.row + .row { border-top: 1px solid color-mix(in oklab, var(--fm-fg) 18%, transparent); }
.link {
  display: grid;
  grid-template-columns: 2.25rem minmax(0, 1fr) auto;
  align-items: baseline;
  gap: 0.25rem;
  padding-block: clamp(0.3rem, 1.2cqi, 0.6rem);
  color: inherit;
  text-decoration: none;
  outline-offset: 2px;
}
.link:focus-visible { outline: 2px solid currentColor; border-radius: var(--mk-radius-s, 4px); }
.num {
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  font-variant-numeric: tabular-nums;
  color: var(--fm-muted);
}
.mask { display: block; overflow: clip; padding-block: 0.04em 0.12em; margin-block: -0.04em -0.12em; }
.word {
  display: inline-block;
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: clamp(2.25rem, 8.6cqi, 4.5rem);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.04em;
  transform: translateY(115%);
  transition:
    transform var(--mk-duration-base, 240ms) var(--mk-ease-exit, ease),
    translate var(--mk-duration-moderate, 360ms) var(--mk-ease-emphasized, ease),
    color var(--mk-duration-fast, 160ms) linear;
}
.root[data-open] .word {
  transform: none;
  transition:
    transform var(--mk-duration-cinematic, 900ms) var(--mk-ease-emphasized, ease) calc(var(--fm-duration) * 0.3 + var(--i) * var(--fm-stagger)),
    translate var(--mk-duration-moderate, 360ms) var(--mk-ease-emphasized, ease),
    color var(--mk-duration-fast, 160ms) linear;
}
.link:hover .word, .link:focus-visible .word { translate: 0.18em 0; color: var(--fm-hover); }
.root[data-tone='signal'] .link:hover .word, .root[data-tone='signal'] .link:focus-visible .word { text-decoration: underline; text-decoration-thickness: 0.06em; text-underline-offset: 0.12em; }
.here, .foot {
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--fm-muted);
}
.here { white-space: nowrap; }
.here::before { content: '● '; color: var(--fm-fg); }
@container (max-width: 26rem) { .here { font-size: 0; } .here::before { font-size: 0.6875rem; } }
.foot {
  margin: 0;
  padding-top: 0.9rem;
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  opacity: 0;
  transition: opacity var(--mk-duration-fast, 160ms) linear;
}
.root[data-open] .foot { opacity: 1; transition: opacity var(--mk-duration-slow, 560ms) linear calc(var(--fm-duration) * 0.6); }

/* ── Reduced motion: fade only ───────────────────────────────────────── */
.root[data-reduced] .curtain { clip-path: none; opacity: 0; transition: opacity 160ms linear, visibility 0s linear 160ms; }
.root[data-reduced][data-open] .curtain { opacity: 1; transition: opacity 160ms linear, visibility 0s; }
.root[data-reduced] .word,
.root[data-reduced] .toggleLabel > span { transform: none; transition: opacity 160ms linear, color 160ms linear; }
.root[data-reduced] .foot { transition: none; }
.root[data-reduced] .icon > span { transition: none; }
.root[data-reduced] .bar { transition: none; }
